UPDATE job_postings
SET status = #{status}, updated_at = NOW()
WHERE id = #{jobId}

mapper.select:
SELECT * FROM job_postings

    status = 'OPEN'

        AND major = #{major}


        AND (
            title LIKE CONCAT('%', #{keyword}, '%')
            OR description LIKE CONCAT('%', #{keyword}, '%')
        )


        AND min_salary >= #{minSalary}


        AND location = #{location}


ORDER BY created_at DESC

SELECT jp.*, u.username as enterprise_name
FROM job_postings jp
LEFT JOIN users u ON jp.enterprise_user_id = u.id

    jp.status = 'OPEN'

        AND (
            jp.title LIKE CONCAT('%', #{keyword}, '%')
            OR jp.description LIKE CONCAT('%', #{keyword}, '%')
        )


        AND jp.required_major = #{major}


        AND jp.min_experience >= #{minExperience}


        AND jp.max_experience <= #{maxExperience}


        AND jp.min_salary >= #{minSalary}


        AND jp.max_salary <= #{maxSalary}


        AND jp.location LIKE CONCAT('%', #{location}, '%')


ORDER BY jp.created_at DESC

SELECT * FROM job_postings

    enterprise_user_id = #{userId}

        AND status = #{status}


ORDER BY created_at DESC
